WITH FIRST AS( SELECT PLAYER_ID, MIN(EVENT_DATE) AS FIRST FROM ACTIVITY GROUP BY 1 ), RETURNS AS( SELECT A.PLAYER_ID FROM ACTIVITY A JOIN FIRST F ON DATEDIFF(A.EVENT_DATE,F.FIRST)=1 AND A.PLAYER_ID=F.PLAYER_ID) SELECT ROUND(COUNT(DISTINCT R.PLAYER_ID)/COUNT(DISTINCT A.PLAYER_ID),2) AS FRACTION FROM RETURNS R, ACTIVITY A;

